import{_ as e,c as o,o as a,ag as r}from"./chunks/framework._xRlcm3f.js";const b=JSON.parse('{"title":"Metaweblog 通用配置指南","description":"","frontmatter":{},"headers":[],"relativePath":"platforms/metaweblog-metaweblog.md","filePath":"platforms/metaweblog-metaweblog.md","lastUpdated":1790228279000}'),d={name:"platforms/metaweblog-metaweblog.md"};function l(s,t,n,i,g,h){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="metaweblog-通用配置指南" tabindex="-1">Metaweblog 通用配置指南 <a class="header-anchor" href="#metaweblog-通用配置指南" aria-label="Permalink to &quot;Metaweblog 通用配置指南&quot;">​</a></h1><p>通过 <strong>MetaWeblog XML-RPC</strong> 协议，把思源笔记发布到<strong>任何实现了该协议、但插件尚未单独适配</strong>的博客系统。</p><h2 id="一、准备" tabindex="-1">一、准备 <a class="header-anchor" href="#一、准备" aria-label="Permalink to &quot;一、准备&quot;">​</a></h2><ol><li>一个可访问的博客站点，且该站点<strong>提供 MetaWeblog / XML-RPC 远程发布接口</strong>（不是所有博客系统默认开启，需按站点的官方文档确认端点路径）。</li><li>该站点后台的<strong>登录用户名与登录密码</strong>（MetaWeblog 按账号密码鉴权，不使用 Token）。若站点要求独立的应用密码/远程发布密码，请准备该密码。</li><li>你需要<strong>自己确知</strong>两件事，因为通用入口不会替你推断： <ul><li>该站点的 <strong>XML-RPC 端点地址</strong>（即「API 地址」）；</li><li>该站点<strong>文章地址的形态</strong>（即「查看文章链接」模板）。</li></ul></li></ol><h2 id="二、与专用入口的区别" tabindex="-1">二、与专用入口的区别 <a class="header-anchor" href="#二、与专用入口的区别" aria-label="Permalink to &quot;二、与专用入口的区别&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>专用入口（如博客园 / Typecho / Jvue）</th><th>本入口（Metaweblog 通用）</th></tr></thead><tbody><tr><td>API 地址</td><td>按各自约定预设或自动推导</td><td><strong>需要你手动填写</strong></td></tr><tr><td>查看文章链接</td><td>预设为该站的实际形态</td><td><strong>默认留空，需要你填写</strong></td></tr><tr><td>适用对象</td><td>已单独适配的博客系统</td><td>尚未单独适配的任意 MetaWeblog 博客</td></tr></tbody></table><p>因此，若你的博客已有专用入口，<strong>优先用专用入口</strong>；本入口是兜底方案。</p><h2 id="三、配置" tabindex="-1">三、配置 <a class="header-anchor" href="#三、配置" aria-label="Permalink to &quot;三、配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>填什么</th></tr></thead><tbody><tr><td>博客首页</td><td>你的博客首页地址，如 <code>https://blog.example.com</code></td></tr><tr><td>API 地址</td><td>该博客的 MetaWeblog XML-RPC 端点，常见形态为 <code>/xmlrpc.php</code> 或 <code>/action/xmlrpc</code>，<strong>以站点实际为准</strong></td></tr><tr><td>用户名</td><td>该博客后台的登录用户名</td></tr><tr><td>密码</td><td>该博客后台的登录密码（或站点要求的应用密码）</td></tr><tr><td>查看文章链接</td><td>文章地址模板，<code>[postid]</code> 会被替换为文章 ID，如 <code>/?p=[postid]</code>、<code>/archives/[postid]</code></td></tr><tr><td>发布格式</td><td>正文提交格式，默认 HTML，保持默认即可</td></tr><tr><td>图床</td><td>按需选择「当前平台」「PicGo 强烈推荐」或「不使用」</td></tr></tbody></table><blockquote><p>通用入口通过 MetaWeblog 发布时不暴露分类目录选择，因此配置页<strong>没有「发布目录」行</strong>。</p></blockquote><h2 id="四、验证与发布" tabindex="-1">四、验证与发布 <a class="header-anchor" href="#四、验证与发布" aria-label="Permalink to &quot;四、验证与发布&quot;">​</a></h2><ol><li>点「验证」→ 站点连通性与账号校验通过 → 保持「配置已保存并验证通过」。</li><li>快速发布 → 选「Metaweblog 通用」→ 发布。文章提交到该站点。</li><li>点「查看文章」验证链接可打开；打不开时说明「查看文章链接」模板与本站实际形态不符，回到配置页修正。</li></ol><h2 id="五、常见问题" tabindex="-1">五、常见问题 <a class="header-anchor" href="#五、常见问题" aria-label="Permalink to &quot;五、常见问题&quot;">​</a></h2><p><strong>Q：API 地址填什么？</strong> A：填该博客的 MetaWeblog XML-RPC 端点。不同博客系统路径不同，可在博客系统官方文档里确认远程发布端点。</p><p><strong>Q：验证失败或提示账号错误？</strong> A：确认用户名是后台登录用户名、密码是登录密码（该协议不使用 Token）；再确认 API 地址是可访问的 XML-RPC 端点。若站点要求独立的应用密码，请改用应用密码。</p><p><strong>Q：为什么没有「发布目录」？</strong> A：通用入口通过 MetaWeblog 发布时不暴露分类目录选择，文章直接进入站点，因此配置页不提供该行。</p><p><strong>Q：查看文章链接打不开？</strong> A：查看链接按「查看文章链接」模板拼出，而该模板<strong>默认留空</strong>。请按本站文章地址的实际形态填写，例如 <code>/?p=[postid]</code> 或 <code>/index.php/archives/[postid]</code>。</p>',17)])])}const p=e(d,[["render",l]]);export{b as __pageData,p as default};
